import Foundation

/// TipMath's contract: what its port must write. Tips, totals and shares, to the cent.
public protocol TipMathContract {
    /// The percentage for a level of service, from tip-presets.json: poor 10, fair 15, good 18, great 22.
    static func percent(for service: String) throws -> Double

    /// The tip is the bill times the percentage over 100, to the cent; the total is the bill plus the tip. A
    /// negative bill, a percentage outside 0 to 100, or fewer than one person is refused.
    static func breakdown(bill: Double, percent: Double, people: Int) throws -> TipBreakdown

    /// Shares are whole cents and sum to the total; the first shares take the cents left over.
    static func shares(total: Double, people: Int) throws -> [Double]
}
